import{experimentResult,cooling,resourceBalance}from './phy2-models.js?v=20261023-physicscomplete01';
const C={ink:'#faf5ed',muted:'#bad0cd',coral:'#e9b299',mint:'#a8c7bf',dark:'#153141'};const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=x=>Number(Number(x).toFixed(3));const T=(x,y,s,n=17,c=C.ink)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="sans-serif" font-size="${n}" fill="${c}">${esc(s)}</text>`;const L=(x,y,u,v,c=C.muted,w=3)=>`<path d="M${x} ${y}L${u} ${v}" stroke="${c}" stroke-width="${w}" fill="none"/>`;const B=(x,y,w,h,c=C.dark)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${c}" stroke="${C.muted}"/>`;const dot=(x,y,r=5,c=C.coral)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
export const phy2SVG=(body,label)=>`<svg viewBox="0 0 560 440" role="img" aria-label="${esc(label)}">${body}</svg>`;
const cube=(x,y,label)=>`<path d="M${x-35} ${y-25}l12 -12h70l-12 12z" fill="#c8d9d3"/><path d="M${x+35} ${y-25}l12 -12v55l-12 12z" fill="#507684"/><rect x="${x-35}" y="${y-25}" width="70" height="55" rx="6" fill="#8cabae"/>`+T(x,y+9,label,17,C.dark);
export function powerFigure(o={}){let{a='120',b='2',progress=1,revealed=true,movie=false}=o,r=experimentResult('power',a,b),t=4*progress,body=T(280,30,movie?'Same work · different transfer rates':'Work and duration set the power',23);for(let i=0;i<2;i++){let x=175+i*220,duration=movie?[2,4][i]:r.t,f=movie?Math.min(t/duration,1):progress,work=movie?120:r.E,y=300-145*f;body+=L(x,125,x,335,'#7f9eaa',2)+L(x-60,340,x+60,340)+cube(x,y,'Load')+T(x,83,work+' J in'+duration+' s',18)+T(x,110,(work/duration)+' W',21)+T(x,380,'Transferred '+fmt(work*f)+' J',16);}body+=T(280,414,movie?'Model time '+fmt(t)+' s · slower motor finishes at4 s':'P = work ÷ time; model omits losses',15);return phy2SVG(body,`Ideal motor comparison. ${movie?'Each does120J; durations2s and4s, powers60W and30W. At model time'+fmt(t)+'s the lift fraction follows each duration.':r.E+'J in'+r.t+'s gives'+r.value+'W.'} No friction or motor heating; playback can stretch the supplied model time.`);}
export function flowFigure({a='100',b='0.6',kind='efficiency',progress=1,revealed=true}={}){let r=experimentResult(kind,a,b),f=r.useful/r.input,w=60,main=230,split=285,body=T(280,30,kind==='dissipation'?'Nothing disappears from the account':'Useful output / total input',23)+`<path d="M55 ${main-w/2}H${split}V${main+w/2}H55Z" fill="${C.coral}" opacity=".9"/><path d="M${split} ${main-w/2}H485l25 ${w*f/2} -25 ${w*f/2}H${split}Z" fill="${C.mint}"/><path d="M${split} ${main-w/2+w*f}Q${split+15} ${main+w/2} ${split+15} 325H${split+15+w*(1-f)}Q${split+15+w*(1-f)} ${main-w/2+w*f} ${split+w*(1-f)} ${main-w/2+w*f}Z" fill="#cf9686"/>`+T(130,170,'Input '+r.input+' J',21)+T(425,145,'Useful '+fmt(r.useful)+' J',21)+T(375,365,'Other stores '+fmt(r.waste)+' J',19);for(let i=0;i<8;i++){let p=(progress+i/8)%1,x=55+p*450,y=main-w/2+(i+.5)*w/8;if(x>split){if(i/8<f)y=main-w/2+(i+.5)*w/8;else{x=split+25+(i/8-f)*w;y=main+((p-.51)/.49)*85;}}body+=dot(x,y,4,'#fff1dc');}body+=T(280,402,revealed?'Useful fraction '+fmt(f)+' = '+fmt(f*100)+'%':'Predict the named output',21)+T(280,432,'Arrow widths use one scale · markers are symbolic, not energy particles',12);return phy2SVG(body,`${kind}: input${r.input}J, useful${fmt(r.useful)}J and other-store${fmt(r.waste)}J; total conserved. Useful fraction${fmt(f)}. Marker movement shows pathways, not material or a measured transfer rate.`);}
export function coolingFigure({a='1',b='1',progress=1,revealed=true}={}){let k=+a,d=+b,t=10*progress,r=cooling(k,d,t),pad=d===1?14:28,body=T(280,28,'Compare the cooling rate fairly',23)+`<path d="M55 128l14 -14h165l-14 14z" fill="#99acb0"/><path d="M220 128l14 -14v180l-14 14z" fill="#3f5c6b"/>`+B(55,128,165,180,'#576a72')+B(55+pad,128+pad,165-pad*2,180-pad*2,'#c1907c')+T(138,202,'Warm block',17)+T(138,234,revealed?fmt(r.final)+'°C':'Predict drop',21)+T(138,340,'Wall thickness ×'+d,16)+T(138,370,'Conductivity index '+k,16)+L(275,325,520,325)+L(275,325,275,95)+T(395,370,'Model time / min',16)+T(275,78,'°C',15);for(let tick of [0,5,10])body+=T(275+tick*23,347,tick,13);for(let temp of [20,40,60,80])body+=T(254,330-(temp-20)*3.5,temp,13);let path='';for(let n=0;n<=50;n++){let v=cooling(k,d,n/5);path+=(n?'L':'M')+(275+n/5*23)+' '+(325-(v.final-20)*3.5);}body+=`<path d="${path}" fill="none" stroke="${C.mint}" stroke-width="4"/>`+dot(275+t*23,325-(r.final-20)*3.5,7)+T(390,405,'Drop '+fmt(r.drop)+'°C at'+fmt(t)+' min',18)+T(280,434,'Original exponential toy curve · initial80°C, room20°C · no building prediction',12);for(let j=0;j<4;j++){let x=200+((progress+j/4)%1)*45;body+=L(x,170+j*27,x+9,170+j*27,C.coral,2);}return phy2SVG(body,`Original cooling illustration with conductivity index${k}, thickness index${d}, initial80°C, room20°C. At${fmt(t)} model minutes final${fmt(r.final)}°C, drop${fmt(r.drop)}°C. Equal mass/area and fixed surroundings; curve not calibrated material data. Energy transfers outward; no energy created.`);}
export function resourceFigure({a='20',b='windy',progress=1,revealed=true}={}){let r=resourceBalance(+a,b),ang=progress*360,body=T(280,28,'Match supply to demand in one snapshot',22)+L(125,210,125,330,'#b9cfd0',9)+`<g transform="rotate(${ang} 125 195)">`+[0,120,240].map(n=>`<path d="M125 195l-8 -85 20 -8 -7 83z" transform="rotate(${n} 125 195)" fill="#bcd1cd"/>`).join('')+'</g>'+dot(125,195,12)+B(345,153,150,140)+T(420,190,'Demand '+r.demand,21)+T(420,228,'Wind '+r.used,20)+T(420,264,revealed?'Backup '+r.backup:'Predict backup',19)+L(170,220,340,220,C.mint,7)+L(280,300,340,270,C.coral,5)+T(270,340,'Backup supply',16)+T(125,370,'Capacity '+r.capacity,18)+T(280,401,r.weather+': output '+r.wind+' · no storage',18)+T(280,433,'Original units, not weather forecasts · symbolic rotor speed',12);return phy2SVG(body,`Original ${r.weather} wind snapshot: installed capacity${r.capacity}, output${r.wind}, demand${r.demand}, wind used${r.used}, backup${r.backup}, surplus${r.surplus}. No storage or price model; rotor speed is symbolic, no forecast.`);}
export function trendFigure(){let body=T(280,30,'Original electricity mix ·100 units each',22),cols=['#dcb095','#a7c7ba','#9ab8c7'];for(let[j,values]of [[60,20,20],[20,50,30]].entries()){let y=340;for(let[i,v]of values.entries()){y-=v*2;body+=`<rect x="${130+j*220}" y="${y}" width="90" height="${v*2}" fill="${cols[i]}"/>`+T(175+j*220,y+v,values[i],17,C.dark);}body+=T(175+j*220,375,j?'Later':'Earlier',17);}body+=T(280,95,'Coal / renewables / nuclear',18)+T(280,415,'Renewables20%→50%: +30 points, +150% relative',17);return phy2SVG(body,'Fictional100-unit electricity mixes: earlier coal60 renewables20 nuclear20; later coal20 renewables50 nuclear30. Renewable share rises30 percentage points or150% relative. Not national data or causal proof.');}
const rows={power:['P = E/t = W/t','Energy/work: J · time: s · power: W','One watt = one joule per second'],dissipation:['Closed account: total stays constant','Useful output + other stores = input','Dissipated: spread into less useful stores'],insulation:['Compare equal starting conditions','Lower conductivity or thicker walls → slower conduction','Repeats, equal time intervals and controlled variables'],efficiency:['Useful energy/input energy OR useful power/input power','Unitless fraction ×100 = percentage','Input = useful output / decimal efficiency'],resources:['Finite fuels: coal, oil, gas, nuclear','Renewable: biofuel, wind, hydro, geothermal','Also tides, sunlight, water waves']};
export function physicsTransferFigure(o={}){if(o.concealed)return phy2SVG(T(280,220,'Predict, then reveal evidence',23),'Evidence concealed until prediction');let k=(o.kind||'power').replace(/-(model|data)$/,'');if(o.kind?.endsWith('-model'))return k==='power'?powerFigure(o):k==='insulation'?coolingFigure(o):k==='resources'?resourceFigure(o):flowFigure({...o,kind:k});if(k==='resources'&&o.state==='4')return trendFigure();let list=rows[k];return phy2SVG(T(280,35,'Use quantities, evidence and purpose',22)+list.map((s,i)=>T(280,130+i*90,s,16)).join('')+T(280,430,'Original teaching representation · state assumptions and boundaries',12),list.join('. '));}
